17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Locale;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.service.ClinicService;
23	import org.springframework.samples.petclinic.util.HashUtils;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Owns the household-identity concern: the single place that decides which owners belong to
28	 * the same household and derives the shared household id they carry.
29	 *
30	 * <p>Keeping this in one place means the shared household id and the household-membership
31	 * lookup can never drift apart: two owners belong to the same household exactly when the
32	 * identity fields this resolver keys on (their normalized last name and address) agree, and
33	 * for that household they derive an identical id.
34	 *
35	 * <p>The household id is formatted {@code 'HH-<HEX12>'} where HEX12 is the first twelve
36	 * upper-case hex characters of the SHA-256 digest of the normalized last name and address
37	 * joined by '|'.
38	 */
39	@Component
40	public class HouseholdResolver {
41	
42	    private final ClinicService clinicService;
43	
44	    private final AddressNormalizer addressNormalizer;
45	
46	    public HouseholdResolver(ClinicService clinicService, AddressNormalizer addressNormalizer) {
47	        this.clinicService = clinicService;
48	        this.addressNormalizer = addressNormalizer;
49	    }
50	
51	    /**
52	     * The stable, shared household identifier for {@code owner}. Owners in the same household
53	     * (same normalized last name and address) derive an identical id.
54	     *
55	     * @param owner the owner whose household id is derived; its address is read in the same
56	     *              canonical form used for household comparison
57	     * @return the {@code 'HH-<HEX12>'} household id
58	     */
59	    public String householdId(Owner owner) {
60	        String key = normalizeIdentity(owner.getLastName()) + "|" + addressKey(owner);
61	        return "HH-" + HashUtils.sha256HexPrefix(key, 12);
62	    }
63	
64	    /**
65	     * Whether an existing owner already belongs to {@code owner}'s household, so an owner
66	     * flagged {@code sharesHousehold} has a household to join.
67	     *
68	     * @param owner the owner about to be created
69	     * @return {@code true} if an already-registered owner shares this owner's household
70	     */
71	    public boolean householdExists(Owner owner) {
72	        String lastNameKey = normalizeIdentity(owner.getLastName());
73	        String addressKey = addressKey(owner);
74	        return this.clinicService.findAllOwners().stream()
75	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
76	                && addressKey(existing).equals(addressKey));
77	    }
78	
79	    /** The owner's address in the canonical form under which households are compared. */
80	    private String addressKey(Owner owner) {
81	        return addressNormalizer.normalize(owner.getAddress());
82	    }
83	
84	    /**
85	     * Normalize a value for household-identity comparison: null becomes an empty string,
86	     * surrounding whitespace is trimmed, internal whitespace runs collapse to a single
87	     * space, and the result is lower-cased.
88	     */
89	    private static String normalizeIdentity(String value) {
90	        if (value == null) {
91	            return "";
92	        }
93	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
94	    }
95	}
