16	
17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
38	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
39	import org.springframework.samples.petclinic.rest.controller.HouseholdResolver;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.samples.petclinic.util.HashUtils;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Minimal syntactic check for an email address: a non-empty local part, a single
67	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
70	
71	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
72	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
73	
74	    /** Dedicated audit logger; emits an audit line on successful owner create. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final TelephoneNormalizer telephoneNormalizer;
86	
87	    private final AddressNormalizer addressNormalizer;
88	
89	    private final CityRegionResolver cityRegionResolver;
90	
91	    private final HouseholdResolver householdResolver;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 TelephoneNormalizer telephoneNormalizer,
98	                                 AddressNormalizer addressNormalizer,
99	                                 CityRegionResolver cityRegionResolver,
100	                                 HouseholdResolver householdResolver) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	        this.telephoneNormalizer = telephoneNormalizer;
106	        this.addressNormalizer = addressNormalizer;
107	        this.cityRegionResolver = cityRegionResolver;
108	        this.householdResolver = householdResolver;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        if (owner.getRegistrationDate() == null) {
142	            owner.setRegistrationDate(LocalDate.now());
143	        }
144	        // A supplied registration date may not be later than the server's current date.
145	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
146	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
147	        }
148	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
149	        LocalDate registrationDate = owner.getRegistrationDate();
150	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
151	            .map(Owner::getRegistrationDate)
152	            .filter(registrationDate::equals)
153	            .count();
154	        if (ownersCreatedThatDay >= 100) {
155	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
156	        }
157	        String address = addressNormalizer.normalize(owner.getAddress());
158	        if (address.isBlank()) {
159	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
160	        }
161	        owner.setAddress(address);
162	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
163	        if (telephone == null) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
167	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	        }
169	        owner.setTelephone(telephone);
170	        String email = owner.getEmail();
171	        if (email != null) {
172	            email = email.trim();
173	            if (!EMAIL_PATTERN.matcher(email).matches()) {
174	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
175	            }
176	            owner.setEmail(email.toLowerCase(Locale.ROOT));
177	        }
178	        // A postcode is optional, but when supplied it must be four digits and valid for the
179	        // owner's city per the fixed region table; a city with no known region accepts any
180	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
181	        String postcode = owner.getPostcode();
182	        if (postcode != null) {
183	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
184	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
185	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
186	            }
187	        }
188	        // The owner's telephone and email are now in their canonical, stored form.
189	        // Establish the household id before the duplicate check so the candidate's whole
190	        // identity key can be compared against the existing owners': only an owner that
191	        // deliberately shares an existing household (same normalized last name and address)
192	        // is assigned that household's shared id; a plain new owner has no household id, so
193	        // its identity key is decided by telephone and email alone.
194	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
195	                && householdResolver.householdExists(owner)) {
196	            owner.setHouseholdId(householdResolver.householdId(owner));
197	        }
198	        if (isDuplicateOwner(owner)) {
199	            return new ResponseEntity<>(HttpStatus.CONFLICT);
200	        }
201	        String cityKey = normalizeIdentity(owner.getCity());
202	        long ownersInCity = this.clinicService.findAllOwners().stream()
203	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
204	            .count();
205	        if (ownersInCity >= 50) {
206	            return new ResponseEntity<>(HttpStatus.CONFLICT);
207	        }
208	        owner.setCustomerCode(customerCode(owner));
209	        owner.setNamesakeCount(namesakeCount(owner));
210	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
211	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
212	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
213	        // still share an existing owner's last name and postcode while carrying a different
214	        // telephone. When it does, it is created but flagged as a possible duplicate of that
215	        // existing owner; otherwise the flag is false and no reference is recorded.
216	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
217	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
218	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
219	        this.clinicService.saveOwner(owner);
220	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
221	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
222	            ownerMapper.membershipLevel(owner));
223	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
224	        headers.setLocation(UriComponentsBuilder.newInstance()
225	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
226	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    /**
230	     * Whether {@code candidate} collides with an already-registered owner under the single
231	     * identity rule enforced on create. This is the one point at which a new owner is
232	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
233	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
234	     * email (or an empty string when absent) and the householdId joined by '|'. The
235	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
236	     * the telephone is part of the key, two members of the same household (same householdId)
237	     * with different telephones have different identityKeys and are both allowed.
238	     *
239	     * <p>The candidate arrives with its telephone and email already normalized and its
240	     * household id already derived, and each existing owner is stored in the same canonical
241	     * form, so an identityKey match means the two owners are genuinely the same identity.
242	     *
243	     * @param candidate the fully-normalized owner about to be created
244	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
245	     */
246	    private boolean isDuplicateOwner(Owner candidate) {
247	        String identityKey = OwnerMapper.identityKey(candidate);
248	        return this.clinicService.findAllOwners().stream()
249	            .map(OwnerMapper::identityKey)
250	            .anyMatch(identityKey::equals);
251	    }
252	
253	    /**
254	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
255	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
256	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
257	     * postcode while carrying a different telephone — a likely re-registration of the same
258	     * person under a new number. Both must supply a postcode for a match to be possible; when
259	     * several existing owners qualify the lowest id is returned so the result is deterministic.
260	     *
261	     * @param candidate the fully-normalized owner about to be created
262	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
263	     */
264	    private Integer possibleDuplicateOf(Owner candidate) {
265	        String postcode = candidate.getPostcode();
266	        if (postcode == null) {
267	            return null;
268	        }
269	        String lastNameKey = normalizeIdentity(candidate.getLastName());
270	        return this.clinicService.findAllOwners().stream()
271	            .filter(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
272	                && postcode.equals(existing.getPostcode())
273	                && !postcode.isBlank()
274	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
275	            .map(Owner::getId)
276	            .filter(java.util.Objects::nonNull)
277	            .min(Integer::compareTo)
278	            .orElse(null);
279	    }
280	
281	    /**
282	     * Normalize a value for identity comparison: null becomes an empty
283	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
284	     * to a single space, and the result is lower-cased.
285	     */
286	    private static String normalizeIdentity(String value) {
287	        if (value == null) {
288	            return "";
289	        }
290	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
291	    }
292	
293	    /**
294	     * Build the customer code assigned to {@code owner} on create, formatted
295	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
296	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
297	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
298	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
299	     */
300	    private String customerCode(Owner owner) {
301	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
302	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
303	        return region + "-" + hash8;
304	    }
305	
306	    /**
307	     * The number of existing owners that share {@code owner}'s firstName and lastName,
308	     * compared case-insensitively. The candidate is not yet stored at the point this is
309	     * assigned, so it does not count itself. This is the value stored as the owner's
310	     * namesakeCount on create.
311	     */
312	    private int namesakeCount(Owner owner) {
313	        return (int) this.clinicService.findAllOwners().stream()
314	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
315	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
316	            .count();
317	    }
318	
319	    /**
320	     * Roll a registration date forward to the next business day: a Saturday or Sunday
321	     * advances to the following Monday, and a weekday is returned unchanged.
322	     */
323	    private static LocalDate toBusinessDay(LocalDate date) {
324	        return switch (date.getDayOfWeek()) {
325	            case SATURDAY -> date.plusDays(2);
326	            case SUNDAY -> date.plusDays(1);
327	            default -> date;
328	        };
329	    }
330	
331	    /**
332	     * Build the membership number assigned on create, formatted
333	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
334	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
335	     */
336	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
337	        String yy = String.format("%02d", registrationDate.getYear() % 100);
338	        return customerCode + "-M" + yy;
339	    }
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
344	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
345	        if (currentOwner == null) {
346	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
347	        }
348	        currentOwner.setAddress(ownerFieldsDto.getAddress());
349	        currentOwner.setCity(ownerFieldsDto.getCity());
350	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
351	        currentOwner.setLastName(ownerFieldsDto.getLastName());
352	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
353	        this.clinicService.saveOwner(currentOwner);
354	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Transactional
359	    @Override
360	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
361	        Owner owner = this.clinicService.findOwnerById(ownerId);
362	        if (owner == null) {
363	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
364	        }
365	        this.clinicService.deleteOwner(owner);
366	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
367	    }
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
372	        Owner owner = this.clinicService.findOwnerById(ownerId);
373	        if (owner == null) {
374	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
375	        }
376	        HttpHeaders headers = new HttpHeaders();
377	        Pet pet = petMapper.toPet(petFieldsDto);
378	        owner.setId(ownerId);
379	        pet.setOwner(owner);
380	        pet.getType().setName(null);
381	        this.clinicService.savePet(pet);
