52	     *                   containing irregular whitespace, casing and abbreviations
53	     * @return the canonical address (trimmed, whitespace-collapsed, upper-cased and with
54	     *         common abbreviations expanded), or the empty string if {@code rawAddress} is
55	     *         {@code null} or blank
56	     */
57	    public String normalize(String rawAddress) {
58	        if (rawAddress == null) {
59	            return "";
60	        }
61	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
62	        if (collapsed.isEmpty()) {
63	            return "";
64	        }
65	        String[] words = collapsed.split(" ");
66	        StringBuilder sb = new StringBuilder(collapsed.length());
67	        for (int i = 0; i < words.length; i++) {
68	            if (i > 0) {
69	                sb.append(' ');
70	            }
71	            sb.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
72	        }
73	        return sb.toString();
